'use strict';

// MODULES //

var isObject = require( '@stdlib/assert/is-object' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var DataSource = require( '@stdlib/plot/vega/mark/data-source' );


// MAIN //

/**
* Tests whether an input value is a mark data source instance.
*
* @param {*} value - value to test
* @returns {boolean} boolean indicating whether an input value is a mark data source instance
*
* @example
* var DataSource = require( '@stdlib/plot/vega/mark/data-source' );
*
* var v = new DataSource({
*     'data': 'foo'
* });
* var bool = isMarkDataSource( v );
* // returns true
*
* bool = isMarkDataSource( {} );
* // returns false
*
* bool = isMarkDataSource( 'foo' );
* // returns false
*/
function isMarkDataSource( value ) {
	return (
		value instanceof DataSource ||

		// The following is a set of rather imperfect heuristics for handling instances originating in a different realm...
		(
			isObject( value ) &&
			isString( value.data )
		)
	);
}


// EXPORTS //

module.exports = isMarkDataSource;
